import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("A vendor name already used in the tenant is refused regardless of case", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const existing = await factory.vendor({ name: uniqueName("Acme Freight") });

  // Act
  const response = await member.post("/api/vendors", {
    data: { name: existing.name.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");
  // Re-read: no second vendor with that name was stored.
  const page = await expectStatus(await member.get("/api/vendors", { params: { q: existing.name } }), 200);
  expect(page.items.map((v: { id: string }) => v.id)).toEqual([existing.id]);
});
